import { pathToFileURL } from "node:url";
import { COMPAT } from "@clutch/compat-layer";
import type { ReactNode, ReactElement, FunctionComponent } from "react";
import { injectReact } from "./react-injector";

const React = COMPAT.react;

export interface ExtensionModule {
	default: ReactNode | (() => ReactNode) | React.ComponentType;
	[key: string]: unknown;
}

export interface LoadedExtension {
	id: string;
	path: string;
	command: string;
	module: ExtensionModule;
	component: ReactElement;
}

export async function loadExtension(
	extensionPath: string,
	command: string,
): Promise<LoadedExtension> {
	injectReact();

	const entryPath = `${extensionPath}/${command}.js`;
	console.error("[LOADER] Loading extension from:", entryPath);
	console.error("[LOADER] Extension path:", extensionPath);
	console.error("[LOADER] Command:", command);

	try {
		const moduleUrl = pathToFileURL(entryPath).href;
		console.error("[LOADER] Importing module from URL:", moduleUrl);

		const module = (await import(
			pathToFileURL(entryPath).href
		)) as ExtensionModule;
		console.error("[LOADER] Module imported successfully");
		console.error("[LOADER] Module exports:", Object.keys(module));
		console.error("[LOADER] Module default type:", typeof module.default);

		let component: ReactElement;
		let defaultExport: unknown = module.default;

		// Handle module namespace objects that have a nested 'default' property
		// This happens with CommonJS modules that export module.exports = { default: Component }
		if (
			defaultExport &&
			typeof defaultExport === "object" &&
			"default" in defaultExport &&
			!React.isValidElement(defaultExport)
		) {
			console.error("[LOADER] Unwrapping nested module.default");
			defaultExport = (defaultExport as Record<string, unknown>).default;
		}

		console.error("[LOADER] defaultExport:", defaultExport);
		console.error(
			"[LOADER] defaultExport.$$typeof:",
			(defaultExport as Record<string, unknown>)?.$$typeof?.toString(),
		);
		console.error(
			"[LOADER] defaultExport.type:",
			(defaultExport as Record<string, unknown>)?.type,
		);
		console.error(
			"[LOADER] defaultExport.props:",
			(defaultExport as Record<string, unknown>)?.props,
		);

		if (React.isValidElement(defaultExport)) {
			console.error("[LOADER] Default export is already a React element");
			console.error(
				"[LOADER] Element type:",
				(defaultExport as unknown as Record<string, unknown>).type,
			);
			console.error(
				"[LOADER] Element props:",
				JSON.stringify(
					(defaultExport as unknown as Record<string, unknown>).props,
				).slice(0, 300),
			);
			component = defaultExport as ReactElement;
		} else if (typeof defaultExport === "function") {
			console.error(
				"[LOADER] Default export is a function component, wrapping with createElement",
			);
			console.error(
				"[LOADER] Function name:",
				(defaultExport as FunctionComponent).name || "anonymous",
			);
			console.error("[LOADER] Calling React.createElement...");
			component = React.createElement(defaultExport as FunctionComponent);
			console.error(
				"[LOADER] Created element, type:",
				(component as unknown as Record<string, unknown>).type,
			);
		} else {
			console.error(
				"[LOADER] Default export is unknown type, wrapping with createElement",
			);
			const Wrapper = () => defaultExport as ReactNode;
			component = React.createElement(Wrapper);
		}
		console.error(
			"[LOADER] Component resolved, isValidElement:",
			React.isValidElement(component),
		);

		const extensionId = `${extensionPath.split("/").pop()}-${command}`;
		console.error("[LOADER] Generated extension ID:", extensionId);

		return {
			id: extensionId,
			path: extensionPath,
			command,
			module,
			component,
		};
	} catch (error) {
		console.error("[LOADER] Failed to load extension:", error);
		throw new Error(
			`Failed to load extension at ${entryPath}: ${error instanceof Error ? error.message : "Unknown error"}`,
		);
	}
}

export function validateExtension(module: unknown): module is ExtensionModule {
	if (typeof module !== "object" || module === null) {
		return false;
	}

	const m = module as Record<string, unknown>;
	return "default" in m;
}
