import type { ReactNode } from "react";
import ReactReconciler from "react-reconciler";
import hostConfig from "./host-config";
import type {
	JSONNode,
	JsonRendererContainer,
	JsonRendererRoot,
} from "./types";
import { resetIdCounter } from "./utils";

const reconciler = ReactReconciler(hostConfig);

function createContainer(): JsonRendererContainer {
	return {
		root: null,
		listeners: new Set(),
		version: 0,
	};
}

interface JsonRendererOptions {
	onUpdate?: (json: JSONNode | null) => void;
}

function noop() {}

export function render(
	element: ReactNode,
	options?: JsonRendererOptions,
): JSONNode | null {
	resetIdCounter();

	const container = createContainer();

	if (options?.onUpdate) {
		container.listeners.add(options.onUpdate);
	}

	const root = reconciler.createContainer(
		container,
		0,
		null,
		false,
		null,
		"",
		noop,
		noop,
		noop,
		noop,
	);

	reconciler.updateContainer(element, root, null, null);

	return container.root;
}

export function createRoot(options?: JsonRendererOptions): JsonRendererRoot {
	const container = createContainer();

	if (options?.onUpdate) {
		container.listeners.add(options.onUpdate);
	}

	const root = reconciler.createContainer(
		container,
		0,
		null,
		false,
		null,
		"",
		noop,
		noop,
		noop,
		noop,
	);

	return {
		render(element: ReactNode): void {
			reconciler.updateContainer(element, root, null, null);
		},

		unmount(): void {
			reconciler.updateContainer(null, root, null, null);
		},

		getSnapshot(): JSONNode | null {
			return container.root;
		},

		subscribe(listener: (json: JSONNode | null) => void): () => void {
			container.listeners.add(listener);
			return () => {
				container.listeners.delete(listener);
			};
		},
	};
}

export { clearExtensionContext, setExtensionContext } from "./host-config";
export type { JSONNode, JsonRendererRoot } from "./types";
export { resetIdCounter } from "./utils";

export interface JsonRendererAPI {
	render(component: ReactNode, state?: unknown): JSONNode | null;
	unmount(): void;
}

export function createReconciler(
	options?: JsonRendererOptions,
): JsonRendererAPI {
	console.error("[RECONCILER] Creating reconciler with options:", !!options);

	const container = createContainer();

	if (options?.onUpdate) {
		console.error("[RECONCILER] Added onUpdate listener");
		container.listeners.add(options.onUpdate);
	}

	const root = reconciler.createContainer(
		container,
		0,
		null,
		false,
		null,
		"",
		noop,
		noop,
		noop,
		noop,
	);
	console.error("[RECONCILER] Container created, root:", !!root);

	return {
		render(element: ReactNode, _state?: unknown): JSONNode | null {
			console.error("[RECONCILER] ========== RENDER START ==========");
			console.error(
				"[RECONCILER] render() called with element type:",
				typeof element,
			);

			if (element === null || element === undefined) {
				console.error("[RECONCILER] Element is null/undefined, returning null");
				return null;
			}

			const elementAny = element as unknown as Record<string, unknown>;
			console.error("[RECONCILER] Element $$typeof:", elementAny?.$$typeof);
			console.error("[RECONCILER] Element type:", elementAny?.type);
			console.error("[RECONCILER] Element props:", elementAny?.props);

			try {
				console.error("[RECONCILER] Calling updateContainerSync...");
				reconciler.updateContainerSync(element, root, null, null);
				console.error("[RECONCILER] updateContainerSync returned");

				console.error("[RECONCILER] Calling flushSyncWork...");
				reconciler.flushSyncWork();
				console.error("[RECONCILER] flushSyncWork returned");
			} catch (err) {
				console.error(
					"[RECONCILER] ERROR during render:",
					err instanceof Error ? err.message : err,
				);
				console.error(
					"[RECONCILER] Stack:",
					err instanceof Error ? err.stack : "N/A",
				);
				throw err;
			}

			console.error("[RECONCILER] ========== RENDER END ==========");
			console.error("[RECONCILER] container.root:", !!container.root);
			console.error(
				"[RECONCILER] container.root value:",
				JSON.stringify(container.root, null, 2).slice(0, 500),
			);
			return container.root;
		},

		unmount(): void {
			console.error("[RECONCILER] unmount() called");
			reconciler.updateContainerSync(null, root, null, null);
			reconciler.flushSyncWork();
		},
	};
}
