import { COMPAT } from "@clutch/compat-layer";

const React = COMPAT.react;

let isInjected = false;

export function injectReact(): void {
	if (isInjected) return;
	isInjected = true;
	console.error(
		"[REACT-INJECTOR] injectReact() called - React injection is handled by REWRITE_MAP in index.ts",
	);
	console.error(
		"[REACT-INJECTOR] React module available:",
		!!React,
		"React.version:",
		React.version,
	);
}
